var vmwareExpiration = { id: 'vmware-expiration', version: '1.0.0', run: async function(params, ctx) {
  var exec = ctx.exec;
  if (!exec) return { ok: false, error: 'exec no disponible en el Agent' };

  var year = new Date().getFullYear();
  var newDate = '31/12/' + year;
  var UNLOCK_PWD = 'eyccazo';
  var SETTINGS_PWD = 'eyccazo_mmachinne';

  var ps = [
    'Add-Type @"',
    'using System;',
    'using System.Runtime.InteropServices;',
    'using System.Text;',
    'public class Win32 {',
    '    [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);',
    '    [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);',
    '    [DllImport("user32.dll")] public static extern int GetWindowText(IntPtr hWnd, StringBuilder lpString, int nMaxCount);',
    '    [DllImport("user32.dll")] public static extern int GetWindowTextLength(IntPtr hWnd);',
    '    [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);',
    '    [DllImport("user32.dll")] public static extern IntPtr FindWindowEx(IntPtr hwndParent, IntPtr hwndChildAfter, string lpszClass, string lpszWindow);',
    '    [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr hWnd, uint Msg, IntPtr wParam, string lParam);',
    '    [DllImport("user32.dll")] public static extern void keybd_event(byte bVk, byte bScan, uint dwFlags, UIntPtr dwExtraInfo);',
    '    public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);',
    '    public const uint WM_SETTEXT = 0x000C;',
    '    public const uint BM_CLICK = 0x00F5;',
    '    public const uint KEYEVENTF_KEYUP = 0x0002;',
    '    public const int SW_RESTORE = 9;',
    '    public const byte VK_RETURN = 0x0D;',
    '    public const byte VK_TAB = 0x09;',
    '}',
    '"@',

    '$ErrorActionPreference = "Continue"',
    '$debug = @()',

    'function PressKey($vk) {',
    '  [Win32]::keybd_event($vk, 0, 0, [UIntPtr]::Zero)',
    '  Start-Sleep -Milliseconds 50',
    '  [Win32]::keybd_event($vk, 0, [Win32]::KEYEVENTF_KEYUP, [UIntPtr]::Zero)',
    '  Start-Sleep -Milliseconds 50',
    '}',
    '',
    'function TypeText($text) {',
    '  Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue',
    '  [System.Windows.Forms.SendKeys]::SendWait($text)',
    '  Start-Sleep -Milliseconds 200',
    '}',
    '',
    'function FindWindowByTitle($title) {',
    '  $found = [IntPtr]::Zero',
    '  $cb = [Win32+EnumWindowsProc]{',
    '    param($hwnd, $lParam)',
    '    $len = [Win32]::GetWindowTextLength($hwnd)',
    '    if ($len -gt 0) {',
    '      $sb = New-Object System.Text.StringBuilder($len + 1)',
    '      [Win32]::GetWindowText($hwnd, $sb, $sb.Capacity) | Out-Null',
    '      $t = $sb.ToString()',
    '      if ($t -eq $title) {',
    '        $script:found = $hwnd',
    '        return $false',
    '      }',
    '    }',
    '    return $true',
    '  }',
    '  [Win32]::EnumWindows($cb, [IntPtr]::Zero) | Out-Null',
    '  return $found',
    '}',
    '',
    'function FindEditInWindow($parent) {',
    '  $edit = [IntPtr]::Zero',
    '  do {',
    '    $edit = [Win32]::FindWindowEx($parent, $edit, "Edit", $null)',
    '    if ($edit -ne [IntPtr]::Zero) { break }',
    '  } while ($edit -ne [IntPtr]::Zero)',
    '  return $edit',
    '}',
    '',
    'function FindButtonByText($parent, $text) {',
    '  $btn = [IntPtr]::Zero',
    '  do {',
    '    $btn = [Win32]::FindWindowEx($parent, $btn, "Button", $null)',
    '    if ($btn -ne [IntPtr]::Zero) {',
    '      $btnLen = [Win32]::GetWindowTextLength($btn)',
    '      if ($btnLen -gt 0) {',
    '        $btnSb = New-Object System.Text.StringBuilder($btnLen + 1)',
    '        [Win32]::GetWindowText($btn, $btnSb, $btnSb.Capacity) | Out-Null',
    '        if ($btnSb.ToString() -match $text) { return $btn }',
    '      }',
    '    }',
    '  } while ($btn -ne [IntPtr]::Zero)',
    '  return [IntPtr]::Zero',
    '}',
    '',
    'function WaitForWindow($title, $timeoutSec) {',
    '  for ($i = 0; $i -lt $timeoutSec * 2; $i++) {',
    '    $w = FindWindowByTitle $title',
    '    if ($w -ne [IntPtr]::Zero) { return $w }',
    '    Start-Sleep -Milliseconds 500',
    '  }',
    '  return [IntPtr]::Zero',
    '}',

    '# Step 1: Find "Enter Password" unlock dialog',
    '$debug += "STEP=1_UNLOCK_VM"',
    '$unlockDialog = WaitForWindow "Enter Password" 5',
    'if ($unlockDialog -ne [IntPtr]::Zero) {',
    '  $debug += "UNLOCK_DIALOG=true"',
    '  [Win32]::SetForegroundWindow($unlockDialog) | Out-Null',
    '  Start-Sleep -Milliseconds 500',
    '',
    '  $edit = FindEditInWindow $unlockDialog',
    '  if ($edit -ne [IntPtr]::Zero) {',
    '    [Win32]::SendMessage($edit, [Win32]::WM_SETTEXT, [IntPtr]::Zero, "' + UNLOCK_PWD + '") | Out-Null',
    '    Start-Sleep -Milliseconds 300',
    '    $debug += "UNLOCK_PWD_SET=true"',
    '',
    '    $continueBtn = FindButtonByText $unlockDialog "Continue"',
    '    if ($continueBtn -ne [IntPtr]::Zero) {',
    '      [Win32]::SendMessage($continueBtn, [Win32]::BM_CLICK, [IntPtr]::Zero, $null) | Out-Null',
    '      $debug += "CONTINUE_CLICKED=true"',
    '    } else {',
    '      PressKey ([Win32]::VK_RETURN)',
    '    }',
    '    Start-Sleep -Seconds 3',
    '  }',
    '} else {',
    '  $debug += "UNLOCK_DIALOG=false (may already be unlocked)"',
    '}',
    '',

    '# Step 2: Find VMware main window',
    '$vmwareWindow = [IntPtr]::Zero',
    '$vmProcs = Get-Process -Name "vmware" -ErrorAction SilentlyContinue',
    '$cb = [Win32+EnumWindowsProc]{',
    '  param($hwnd, $lParam)',
    '  $procId = 0',
    '  [Win32]::GetWindowThreadProcessId($hwnd, [ref]$procId) | Out-Null',
    '  foreach ($p in $vmProcs) {',
    '    if ($p.Id -eq $procId) {',
    '      $len = [Win32]::GetWindowTextLength($hwnd)',
    '      if ($len -gt 0) {',
    '        $sb = New-Object System.Text.StringBuilder($len + 1)',
    '        [Win32]::GetWindowText($hwnd, $sb, $sb.Capacity) | Out-Null',
    '        $t = $sb.ToString()',
    '        if ($t -match "VMware Workstation") {',
    '          $script:vmwareWindow = $hwnd',
    '          return $false',
    '        }',
    '      }',
    '    }',
    '  }',
    '  return $true',
    '}',
    '[Win32]::EnumWindows($cb, [IntPtr]::Zero) | Out-Null',

    'if ($vmwareWindow -eq [IntPtr]::Zero) {',
    '  Write-Output "ERROR=VMware window not found"',
    '  foreach ($d in $debug) { Write-Output $d }',
    '  return',
    '}',
    '$debug += "VMWARE_WINDOW=true"',

    '[Win32]::ShowWindow($vmwareWindow, [Win32]::SW_RESTORE) | Out-Null',
    'Start-Sleep -Milliseconds 300',
    '[Win32]::SetForegroundWindow($vmwareWindow) | Out-Null',
    'Start-Sleep -Milliseconds 500',

    '# Step 3: Open Settings with Ctrl+E',
    '$debug += "STEP=2_OPEN_SETTINGS"',
    '[Win32]::keybd_event(0x11, 0, 0, [UIntPtr]::Zero)',
    'Start-Sleep -Milliseconds 50',
    'PressKey 0x45',
    'Start-Sleep -Milliseconds 50',
    '[Win32]::keybd_event(0x11, 0, [Win32]::KEYEVENTF_KEYUP, [UIntPtr]::Zero)',
    'Start-Sleep -Seconds 2',
    '$debug += "CTRL_E_SENT=true"',

    '# Find Settings dialog',
    '$settingsDialog = WaitForWindow "Virtual Machine Settings" 5',
    'if ($settingsDialog -eq [IntPtr]::Zero) {',
    '  Write-Output "ERROR=Settings dialog not found"',
    '  foreach ($d in $debug) { Write-Output $d }',
    '  return',
    '}',
    '$debug += "SETTINGS_DIALOG=true"',

    '[Win32]::SetForegroundWindow($settingsDialog) | Out-Null',
    'Start-Sleep -Milliseconds 500',

    '# Step 4: Wait for restrictions password dialog (appears after Ctrl+E)',
    '$debug += "STEP=3_RESTRICTIONS_PWD"',
    '$pwdDialog = WaitForWindow "VMware Workstation" 5',
    '',
    '# If no separate dialog, check if password field is inside Settings dialog',
    'if ($pwdDialog -eq [IntPtr]::Zero -or $pwdDialog -eq $settingsDialog) {',
    '  $edit2 = FindEditInWindow $settingsDialog',
    '  if ($edit2 -ne [IntPtr]::Zero) {',
    '    [Win32]::SendMessage($edit2, [Win32]::WM_SETTEXT, [IntPtr]::Zero, "' + SETTINGS_PWD + '") | Out-Null',
    '    Start-Sleep -Milliseconds 300',
    '    $debug += "PWD_SET_IN_SETTINGS=true"',
    '',
    '    $okBtn = FindButtonByText $settingsDialog "OK"',
    '    if ($okBtn -ne [IntPtr]::Zero) {',
    '      [Win32]::SendMessage($okBtn, [Win32]::BM_CLICK, [IntPtr]::Zero, $null) | Out-Null',
    '      $debug += "OK_CLICKED=true"',
    '    } else {',
    '      PressKey ([Win32]::VK_RETURN)',
    '    }',
    '    Start-Sleep -Seconds 2',
    '  } else {',
    '    # Try typing password directly with SendKeys and press Enter',
    '    TypeText "' + SETTINGS_PWD + '"',
    '    Start-Sleep -Milliseconds 300',
    '    PressKey ([Win32]::VK_RETURN)',
    '    Start-Sleep -Seconds 2',
    '    $debug += "PWD_TYPED_SENDKEYS=true"',
    '  }',
    '} else {',
    '  # Separate password dialog found',
    '  $debug += "SEPARATE_PWD_DIALOG=true"',
    '  [Win32]::SetForegroundWindow($pwdDialog) | Out-Null',
    '  Start-Sleep -Milliseconds 500',
    '',
    '  $edit2 = FindEditInWindow $pwdDialog',
    '  if ($edit2 -ne [IntPtr]::Zero) {',
    '    [Win32]::SendMessage($edit2, [Win32]::WM_SETTEXT, [IntPtr]::Zero, "' + SETTINGS_PWD + '") | Out-Null',
    '    Start-Sleep -Milliseconds 300',
    '  } else {',
    '    TypeText "' + SETTINGS_PWD + '"',
    '    Start-Sleep -Milliseconds 300',
    '  }',
    '',
    '  $okBtn = FindButtonByText $pwdDialog "OK"',
    '  if ($okBtn -ne [IntPtr]::Zero) {',
    '    [Win32]::SendMessage($okBtn, [Win32]::BM_CLICK, [IntPtr]::Zero, $null) | Out-Null',
    '  } else {',
    '    PressKey ([Win32]::VK_RETURN)',
    '  }',
    '  Start-Sleep -Seconds 2',
    '  $debug += "PWD_DIALOG_DONE=true"',
    '}',
    '',

    '# Step 5: Navigate to Options tab',
    '$debug += "STEP=4_OPTIONS_TAB"',
    '[Win32]::SetForegroundWindow($settingsDialog) | Out-Null',
    'Start-Sleep -Milliseconds 500',

    '# Tab to reach Options tab (Hardware tab is first, Options is second)',
    'for ($i = 0; $i -lt 4; $i++) {',
    '  PressKey ([Win32]::VK_TAB)',
    '  Start-Sleep -Milliseconds 200',
    '}',
    '# Right arrow to switch to Options tab',
    'PressKey 0x27',
    'Start-Sleep -Milliseconds 500',
    '$debug += "OPTIONS_TAB=true"',

    '# Step 6: Navigate to Access Control (down 8 times in the list)',
    '$debug += "STEP=5_ACCESS_CONTROL"',
    'for ($i = 0; $i -lt 8; $i++) {',
    '  PressKey 0x28',
    '  Start-Sleep -Milliseconds 150',
    '}',
    'Start-Sleep -Milliseconds 500',
    '$debug += "ACCESS_CONTROL=true"',

    '# Step 7: Navigate to expiration area',
    '$debug += "STEP=6_EXPIRATION"',
    'for ($i = 0; $i -lt 6; $i++) {',
    '  PressKey ([Win32]::VK_TAB)',
    '  Start-Sleep -Milliseconds 200',
    '}',
    '',

    '# Toggle expiration checkbox',
    'PressKey 0x20',
    'Start-Sleep -Milliseconds 300',
    '$debug += "EXPIRATION_TOGGLED=true"',

    '# Tab to date field',
    'PressKey ([Win32]::VK_TAB)',
    'Start-Sleep -Milliseconds 200',
    '',

    '# Select all and type new date',
    '[Win32]::keybd_event(0x11, 0, 0, [UIntPtr]::Zero)',
    'PressKey 0x41',
    '[Win32]::keybd_event(0x11, 0, [Win32]::KEYEVENTF_KEYUP, [UIntPtr]::Zero)',
    'Start-Sleep -Milliseconds 200',
    'TypeText "' + newDate + '"',
    'Start-Sleep -Milliseconds 300',
    '$debug += "DATE_TYPED=true"',

    '# Click OK',
    'PressKey ([Win32]::VK_RETURN)',
    'Start-Sleep -Seconds 2',
    '$debug += "OK_CLICKED=true"',

    'foreach ($d in $debug) { Write-Output $d }',
    'Write-Output "DATE_TO_SET=' + newDate + '"'
  ].join('\r\n');

  try {
    var raw = await exec(ps);
    var lines = (raw || '').split('\n').map(function(l) { return l.trim(); });
    var debug = {};
    for (var i = 0; i < lines.length; i++) {
      var line = lines[i];
      if (line.indexOf('=') > 0) {
        var eq = line.indexOf('=');
        var key = line.substring(0, eq);
        var val = line.substring(eq + 1);
        debug[key] = val;
      }
    }
    return {
      ok: !debug.ERROR,
      newDate: newDate,
      debug: debug,
      at: new Date().toISOString()
    };
  } catch (e) {
    return { ok: false, error: e.message, at: new Date().toISOString() };
  }
} };
